                            reference_sync_request: FAA_FCS_Coordination.Request_Indication.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val fd_onValue: FAA_FCS_Coordination.FD_Indication.Type = get_fd_on().get
    if(!fd_on(fd_onValue)) {
