    val fcs_failedValue: FAA_FCS_Coordination.FCS_Failed_Indication.Type = get_fcs_failed().get
    if(!fcs_failed(fcs_failedValue)) {
      testFailures = testFailures :+ st"'fcs_failed' did not match expected: value of the outgoing data port is ${fcs_failedValue}"
    }
    val reference_sync_requestValue: FAA_FCS_Coordination.Request_Indication.Type = get_reference_sync_request().get
    if(!reference_sync_request(reference_sync_requestValue)) {
      testFailures = testFailures :+ st"'reference_sync_request' did not match expected: value of the outgoing data port is ${reference_sync_requestValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


